<script setup lang="ts">import type {Metric} from './types';defineProps<{metrics:Metric[]}>();function main(x:Metric){if(x.state==='UNASSIGNED')return '未分配';if(x.state==='EMPTY')return x.key==='examAverage'?'暂无正式成绩':'暂无正式评价';return `${x.value}${x.unit||''}`}</script>
<template><div class="metric-grid"><div v-for="item in metrics" :key="item.key" class="metric"><span>{{item.label}}</span><strong>{{main(item)}}</strong></div></div></template>
<style scoped>.metric-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.metric{min-width:0;padding:14px;border:1px solid #e8e8e8;border-radius:6px;background:#fff}.metric span{color:#6f6f6f;font-size:14px}.metric strong{display:block;margin:7px 0 3px;color:var(--app-primary);font-size:30px;line-height:1.15}.metric p{margin:0;color:#939393;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:1100px){.metric-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.metric-grid{grid-template-columns:repeat(2,1fr)}}</style>
